struct Counter {
    count: i32,
}

impl Counter {
    fn new() -> Counter {
        return Counter { count: 0 };
    }

    fn increment(&mut self) {
        self.count = self.count + 1;
    }

    fn get(&self) -> i32 {
        return self.count;
    }
}

fn main() {
    let mut c = Counter::new();
    let mut i = 0;
    while i < 5 {
        c.increment();
        i = i + 1;
    }
    print(c.get());
}

fn fib(n: i32) -> i32 {
    if n <= 1 {
        return n;
    }
    return fib(n - 1) + fib(n - 2);
}

fn main() {
    print(fib(10));
}

